package cn.zhuatech.aiops.controller; import cn.zhuatech.aiops.common.ApiResponse; import cn.zhuatech.aiops.dto.AiopsDto.*; import cn.zhuatech.aiops.service.AiopsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final AiopsService service;public OperationsAdminController(AiopsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
